# ENGR 311 (Transform Calculus & PDEs, Dr. Su, Fall 2026) — theory/recall bank. Zill AEM: Ch 4, Ch 12, Ch 13 (13.1–13.6).
C = "engr311"
S4, S12, S13, PS = "Ch 4 slides – The Laplace Transform", "Ch 12 slides – Orthogonal Functions & Fourier Series", "Ch 13 slides – Boundary-Value Problems", "Midterm 2 procedures sheet"
Q = []
def mcq(id, topic, q, choices, ans, exp, src): Q.append(dict(id=f"e311-{id}", course=C, topic=topic, type="mcq", question=q, choices=choices, answer=ans, explanation=exp, source=src))
def tf(id, topic, q, ans, exp, src): Q.append(dict(id=f"e311-{id}", course=C, topic=topic, type="tf", question=q, answer=ans, explanation=exp, source=src))
def sa(id, topic, q, ans, exp, src, kw=()): Q.append(dict(id=f"e311-{id}", course=C, topic=topic, type="short", question=q, answer=ans, explanation=exp, source=src, keywords=list(kw)))

T = "Laplace basics"
mcq("lt-01", T, "The Laplace transform of $f(t)$ is defined as:", ["$\\int_0^\\infty e^{-st}f(t)\\,dt$", "$\\int_{-\\infty}^\\infty e^{-st}f(t)\\,dt$", "$\\int_0^\\infty e^{st}f(t)\\,dt$", "$\\int_0^t e^{-s\\tau}f(\\tau)\\,d\\tau$"], 0, "It is an improper integral that converges for $s$ large enough.", S4)
sa("lt-02", T, "State sufficient conditions for $\\mathcal L\\{f(t)\\}$ to exist for $s>c$.", "$f$ is piecewise continuous on $[0,\\infty)$ and of exponential order $c$: $|f(t)|\\le Me^{ct}$ for $t>T$.", "These are sufficient, not necessary. $t^{-1/2}$ has a transform even though it isn't piecewise continuous at 0.", S4, ["piecewise continuous", "exponential order"])
tf("lt-03", T, "$f(t)=e^{t^2}$ has a Laplace transform.", False, "It grows faster than any $e^{ct}$, so it is not of exponential order and the integral diverges.", S4)
mcq("lt-04", T, "$\\mathcal L\\{t^n\\}$ for $n=0,1,2,\\dots$ is:", ["$\\dfrac{n!}{s^{n+1}}$", "$\\dfrac{n!}{s^n}$", "$\\dfrac{1}{s^{n+1}}$", "$\\dfrac{(n+1)!}{s^{n+1}}$"], 0, "For example, $\\mathcal L\\{1\\}=1/s$ and $\\mathcal L\\{t\\}=1/s^2$.", S4)
mcq("lt-05", T, "$\\mathcal L\\{\\sin kt\\}$ is:", ["$\\dfrac{k}{s^2+k^2}$", "$\\dfrac{s}{s^2+k^2}$", "$\\dfrac{k}{s^2-k^2}$", "$\\dfrac{1}{s^2+k^2}$"], 0, "$\\mathcal L\\{\\cos kt\\}=s/(s^2+k^2)$. Sinh and cosh have $s^2-k^2$.", S4)
mcq("lt-06", T, "$\\mathcal L\\{e^{at}\\}$ is:", ["$\\dfrac{1}{s-a}$, for $s>a$", "$\\dfrac{1}{s+a}$", "$\\dfrac{a}{s-a}$", "$\\dfrac{s}{s-a}$"], 0, "Integrate $e^{-(s-a)t}$ from 0 to ∞. It converges only when $s>a$.", S4)
tf("lt-07", T, "The Laplace transform is linear: $\\mathcal L\\{\\alpha f+\\beta g\\}=\\alpha F(s)+\\beta G(s)$.", True, "Linearity, together with the inverse transform, is what makes partial fractions work.", S4)
tf("lt-08", T, "$\\mathcal L\\{f(t)g(t)\\}=F(s)G(s)$.", False, "The transform of a product is NOT the product of transforms. $F(s)G(s)$ is the transform of the convolution $f*g$.", S4)
tf("lt-09", T, "If $f$ is piecewise continuous and of exponential order, then $F(s)\\to0$ as $s\\to\\infty$.", True, "So a function like $F(s)=s/(s+1)$ cannot be the transform of such an $f$.", S4)

T = "Transforms of derivatives & IVPs"
mcq("dv-01", T, "$\\mathcal L\\{y''(t)\\}$ equals:", ["$s^2Y(s)-sy(0)-y'(0)$", "$s^2Y(s)-y(0)-sy'(0)$", "$s^2Y(s)+sy(0)+y'(0)$", "$sY(s)-y(0)$"], 0, "In general: $\\mathcal L\\{f^{(n)}\\}=s^nF-s^{n-1}f(0)-\\dots-f^{(n-1)}(0)$.", S4)
sa("dv-02", T, "Outline the steps for solving a linear constant-coefficient IVP with the Laplace transform.", "1) Transform both sides, using the derivative formula with the initial conditions. 2) Solve the algebraic equation for $Y(s)$. 3) Use partial fractions or the theorems to find $y(t)=\\mathcal L^{-1}\\{Y(s)\\}$.", "The initial conditions go in at step 1, so you never solve for arbitrary constants.", S4, ["transform", "solve for Y(s)", "inverse transform"])
tf("dv-03", T, "The Laplace method builds the initial conditions in automatically, so no constants need to be fitted at the end.", True, "That is its main advantage over undetermined coefficients for IVPs.", S4)
mcq("dv-04", T, "$\\mathcal L\\left\\{\\int_0^t f(\\tau)\\,d\\tau\\right\\}$ equals:", ["$F(s)/s$", "$sF(s)$", "$F(s)-f(0)$", "$F'(s)$"], 0, "This is the special case $g=1$ of the convolution theorem.", S4)

T = "Translation theorems"
mcq("tr-01", T, "First translation theorem: $\\mathcal L\\{e^{at}f(t)\\}=$", ["$F(s-a)$", "$F(s+a)$", "$e^{-as}F(s)$", "$e^{as}F(s)$"], 0, "Multiplying by an exponential in $t$ shifts the transform along the $s$-axis.", S4)
mcq("tr-02", T, "$\\mathcal L\\{e^{-2t}\\cos3t\\}$ is:", ["$\\dfrac{s+2}{(s+2)^2+9}$", "$\\dfrac{s-2}{(s-2)^2+9}$", "$\\dfrac{s}{(s+2)^2+9}$", "$\\dfrac{3}{(s+2)^2+9}$"], 0, "Take $s/(s^2+9)$ and replace $s$ with $s+2$ everywhere.", S4)
mcq("tr-03", T, "The unit step function $\\mathcal U(t-a)$ equals:", ["0 for $0\\le t<a$ and 1 for $t\\ge a$", "1 for $t<a$ and 0 for $t\\ge a$", "1 only at $t=a$", "$t-a$ for $t\\ge a$"], 0, "$\\mathcal L\\{\\mathcal U(t-a)\\}=e^{-as}/s$.", S4)
mcq("tr-04", T, "Second translation theorem: $\\mathcal L\\{f(t-a)\\mathcal U(t-a)\\}=$", ["$e^{-as}F(s)$", "$F(s-a)$", "$e^{as}F(s)$", "$F(s)/s$"], 0, "A delay of $a$ in time multiplies the transform by $e^{-as}$.", S4)
mcq("tr-05", T, "The alternative form of the second translation theorem is $\\mathcal L\\{g(t)\\mathcal U(t-a)\\}=$", ["$e^{-as}\\mathcal L\\{g(t+a)\\}$", "$e^{-as}\\mathcal L\\{g(t)\\}$", "$\\mathcal L\\{g(t-a)\\}$", "$e^{as}\\mathcal L\\{g(t+a)\\}$"], 0, "Useful when $g$ is not already written as a shifted function, e.g. $t^2\\,\\mathcal U(t-1)$.", S4)
sa("tr-06", T, "Write $f(t)=\\begin{cases}2 & 0\\le t<3\\\\ -1 & t\\ge3\\end{cases}$ using unit step functions.", "$f(t)=2-3\\,\\mathcal U(t-3)$", "Start with the first piece, then at each break add (new piece − old piece) × $\\mathcal U(t-a)$.", S4, ["2 − 3U(t−3)"])
mcq("tr-07", T, "$\\mathcal L^{-1}\\left\\{\\dfrac{e^{-2s}}{s^2}\\right\\}$ is:", ["$(t-2)\\,\\mathcal U(t-2)$", "$t\\,\\mathcal U(t-2)$", "$e^{-2t}t$", "$(t+2)\\,\\mathcal U(t-2)$"], 0, "$\\mathcal L^{-1}\\{1/s^2\\}=t$, then shift by 2 and switch on at $t=2$.", S4)
tf("tr-08", T, "To invert $\\dfrac{1}{s^2+4s+13}$, complete the square to $(s+2)^2+9$ and use the first translation theorem.", True, "The result is $\\tfrac13e^{-2t}\\sin3t$.", S4)

T = "Operational properties"
mcq("op-01", T, "$\\mathcal L\\{t\\,f(t)\\}$ equals:", ["$-\\dfrac{d}{ds}F(s)$", "$\\dfrac{d}{ds}F(s)$", "$sF(s)$", "$F(s)/s$"], 0, "In general $\\mathcal L\\{t^nf\\}=(-1)^nF^{(n)}(s)$.", S4)
mcq("op-02", T, "The convolution $f*g$ is defined as:", ["$\\int_0^t f(\\tau)g(t-\\tau)\\,d\\tau$", "$\\int_0^\\infty f(\\tau)g(\\tau)\\,d\\tau$", "$f(t)g(t)$", "$\\int_0^t f(\\tau)g(\\tau)\\,d\\tau$"], 0, "Convolution theorem: $\\mathcal L\\{f*g\\}=F(s)G(s)$.", S4)
tf("op-03", T, "Convolution is commutative: $f*g=g*f$.", True, "Substitute $u=t-\\tau$ in the integral to show it.", S4)
sa("op-04", T, "What kind of equation is $f(t)=g(t)+\\int_0^t f(\\tau)h(t-\\tau)d\\tau$, and how does Laplace solve it?", "A Volterra integral equation. The integral is a convolution, so transforming gives $F=G+FH$, which solves to $F=G/(1-H)$. Then invert.", "The same approach works for integro-differential equations such as LRC circuits.", S4, ["Volterra", "convolution", "F = G/(1−H)"])
mcq("op-05", T, "If $f$ is periodic with period $T$, then $\\mathcal L\\{f\\}=$", ["$\\dfrac{1}{1-e^{-sT}}\\int_0^T e^{-st}f(t)\\,dt$", "$\\int_0^T e^{-st}f(t)\\,dt$", "$\\dfrac{1}{1+e^{-sT}}\\int_0^T e^{-st}f(t)\\,dt$", "$T\\int_0^T e^{-st}f(t)\\,dt$"], 0, "You only integrate over one period.", S4)

T = "Dirac delta & systems"
mcq("dd-01", T, "$\\mathcal L\\{\\delta(t-t_0)\\}$ for $t_0>0$ is:", ["$e^{-st_0}$", "$1/s$", "$e^{-st_0}/s$", "1"], 0, "For $t_0=0$: $\\mathcal L\\{\\delta(t)\\}=1$.", S4)
tf("dd-02", T, "The Dirac delta is an ordinary function that equals $\\infty$ at $t_0$ and 0 elsewhere, with $\\int_0^\\infty\\delta(t-t_0)dt=1$.", False, "It is not a function in the usual sense. It's a generalized function, defined as a limit of unit impulses or by its sifting property $\\int f(t)\\delta(t-t_0)dt=f(t_0)$.", S4)
sa("dd-03", T, "What physical situation does $\\delta(t-t_0)$ model on the right side of a spring–mass equation?", "A sudden impulse (a large force acting for a very short time, e.g. a hammer blow) at $t=t_0$, with total impulse 1.", "The response jumps in velocity at $t_0$ while the displacement stays continuous.", S4, ["impulse", "short time", "hammer blow"])
tf("dd-04", T, "The Laplace transform turns a system of linear ODEs with constant coefficients into a system of algebraic equations in $X(s)$, $Y(s)$.", True, "Solve with elimination or Cramer's rule, then invert each one.", S4)

T = "Orthogonal functions"
mcq("of-01", T, "Two functions $f_1$, $f_2$ are orthogonal on $[a,b]$ if:", ["$\\int_a^b f_1f_2\\,dx=0$", "$f_1(x)f_2(x)=0$ for all $x$", "$\\int_a^b (f_1+f_2)\\,dx=0$", "$f_1'=f_2$"], 0, "This is the inner product $(f_1,f_2)$ for real functions.", S12)
tf("of-02", T, "$f_1=x^2$ and $f_2=x^3$ are orthogonal on $[-1,1]$.", True, "$\\int_{-1}^1x^5dx=0$ because $x^5$ is odd on a symmetric interval.", S12)
mcq("of-03", T, "The norm of $\\phi_n$ on $[a,b]$ is:", ["$\\|\\phi_n\\|=\\sqrt{\\int_a^b\\phi_n^2\\,dx}$", "$\\int_a^b\\phi_n\\,dx$", "$\\int_a^b\\phi_n^2\\,dx$", "$\\max|\\phi_n|$"], 0, "$\\|\\phi_n\\|^2$ is the square norm. A set with all norms equal to 1 is orthonormal.", S12)
mcq("of-04", T, "On $[-\\pi,\\pi]$, $\\|\\cos nx\\|$ for $n\\ge1$ equals:", ["$\\sqrt\\pi$", "$\\pi$", "$\\sqrt{2\\pi}$", "1"], 0, "$\\int_{-\\pi}^{\\pi}\\cos^2nx\\,dx=\\pi$. The member $\\phi_0=1$ is different: its norm is $\\sqrt{2\\pi}$.", S12)
mcq("of-05", T, "In an orthogonal series expansion $f=\\sum c_n\\phi_n$, the coefficients are:", ["$c_n=\\dfrac{(f,\\phi_n)}{\\|\\phi_n\\|^2}$", "$c_n=(f,\\phi_n)$", "$c_n=\\|\\phi_n\\|^2$", "$c_n=f(n)$"], 0, "Multiply by $\\phi_m$ and integrate. Orthogonality kills every term except $n=m$.", S12)
tf("of-06", T, "A set $\\{\\phi_n\\}$ is orthogonal with respect to a weight function $w(x)$ if $\\int_a^b w\\,\\phi_m\\phi_n\\,dx=0$ for $m\\ne n$.", True, "Weight functions show up in Sturm–Liouville problems (e.g. Bessel with $w=x$).", S12)
sa("of-07", T, "What is the classic trap when computing $\\int\\cos mx\\cos nx\\,dx$ with product-to-sum formulas?", "Dividing by $m-n$ when $m=n$. The $m=n$ case (the norm) must be done separately using $\\cos^2\\theta=\\tfrac12(1+\\cos2\\theta)$. Special members like $\\phi_0=1$ also need separate handling.", "Straight from the Midterm 2 procedures sheet.", PS, ["m = n separately", "don't divide by m−n", "φ0 special"])

T = "Fourier series"
mcq("fs-01", T, "For the Fourier series of $f$ on $(-p,p)$, the coefficient $a_n$ is:", ["$\\dfrac1p\\int_{-p}^pf(x)\\cos\\dfrac{n\\pi x}{p}dx$", "$\\dfrac{1}{2p}\\int_{-p}^pf(x)\\cos\\dfrac{n\\pi x}{p}dx$", "$\\dfrac2p\\int_{-p}^pf(x)\\cos\\dfrac{n\\pi x}{p}dx$", "$\\int_{-p}^pf(x)\\cos(nx)dx$"], 0, "$a_0=\\frac1p\\int f$, and the series starts with $a_0/2$.", S12)
tf("fs-02", T, "The series $\\frac{a_0}2+\\sum(a_n\\cos\\frac{n\\pi x}p+b_n\\sin\\frac{n\\pi x}p)$ uses $a_0/2$ so that the same formula for $a_n$ works at $n=0$.", True, "So the constant term is the average value of $f$ over the interval.", S12)
mcq("fs-03", T, "At a jump discontinuity $x=c$, the Fourier series of a piecewise-smooth $f$ converges to:", ["$\\dfrac{f(c^+)+f(c^-)}{2}$", "$f(c^+)$", "$f(c^-)$", "0"], 0, "At points where $f$ is continuous, it converges to $f(c)$.", S12)
mcq("fs-04", T, "At the endpoint $x=p$ of $(-p,p)$, the full Fourier series converges to:", ["$\\dfrac{f(-p^+)+f(p^-)}{2}$", "$f(p)$", "0", "$f(0)$"], 0, "The periodic extension joins the end of the interval to its start.", PS)
mcq("fs-05", T, "If $f$ is even on $(-p,p)$, its Fourier series contains:", ["Only $a_0$ and cosine terms ($b_n=0$)", "Only sine terms", "Both sines and cosines", "Only $a_0$"], 0, "$a_n=\\frac2p\\int_0^pf\\cos\\frac{n\\pi x}p dx$.", S12)
mcq("fs-06", T, "The product of two odd functions is:", ["Even", "Odd", "Neither", "Zero"], 0, "even × even = even, odd × odd = even, even × odd = odd.", S12)
tf("fs-07", T, "If $f$ is odd, then $\\int_{-a}^af(x)dx=0$.", True, "For even $f$: $\\int_{-a}^a f=2\\int_0^af$.", S12)
mcq("fs-08", T, "Which function is neither even nor odd?", ["$x+x^2$", "$|x|$", "$x^3$", "$\\cos x$"], 0, "Its even part ($x^2$) contributes to $a_n$ and its odd part ($x$) contributes to $b_n$.", PS)
mcq("fs-09", T, "The Gibbs phenomenon refers to:", ["A persistent overshoot of about 9% near a jump that narrows but does not shrink as more terms are added", "The series diverging at a jump", "Slow convergence of smooth functions", "The series converging to the wrong function"], 0, "The overshoot never goes away, even as $N\\to\\infty$.", S12)
tf("fs-10", T, "A Fourier sine series always gives 0 at $x=0$ and $x=\\pm p$.", True, "Every term $\\sin(n\\pi x/p)$ vanishes there. (Procedures sheet)", PS)
sa("fs-11", T, "Name the three half-range expansions of $f$ defined on $(0,L)$ and the extension each one uses.", "Cosine series (even extension to $(-L,0)$), sine series (odd extension), and full Fourier series (the function repeats with period $L$, i.e. $p=L/2$).", "You only integrate over $(0,L)$, with $p=L$ for cosine or sine.", S12, ["cosine/even", "sine/odd", "full/period L"])
mcq("fs-12", T, "To evaluate a numerical sum like $1-\\frac13+\\frac15-\\dots$ from a Fourier series, you:", ["Plug a convenient $x$ (e.g. 0, $p/2$, $p$) into the series and use the convergence theorem for the left side", "Differentiate the series", "Integrate the series from 0 to $p$", "Set $n=1$"], 0, "Choose $x$ so that $\\cos$ or $\\sin$ gives a clean pattern ($1$, $(-1)^n$, $1,0,-1,0$).", PS)
tf("fs-13", T, "The complex Fourier series is $\\sum_{n=-\\infty}^\\infty c_ne^{in\\pi x/p}$ with $c_n=\\frac1{2p}\\int_{-p}^pf(x)e^{-in\\pi x/p}dx$.", True, "It is equivalent to the real form, using Euler's formula.", S12)
mcq("fs-14", T, "$\\sin n\\pi$ and $\\cos n\\pi$ for integer $n$ equal:", ["$0$ and $(-1)^n$", "$(-1)^n$ and $0$", "$1$ and $0$", "$0$ and $1$"], 0, "This is the most common simplification step when computing coefficients.", PS)

T = "PDEs & separation of variables"
mcq("pd-01", T, "The 1-D heat equation is:", ["$k\\,u_{xx}=u_t$", "$a^2u_{xx}=u_{tt}$", "$u_{xx}+u_{yy}=0$", "$u_t+u_x=0$"], 0, "The wave equation is $a^2u_{xx}=u_{tt}$ and Laplace's equation is $u_{xx}+u_{yy}=0$.", S13)
mcq("pd-02", T, "Classify by $B^2-4AC$: the heat, wave and Laplace equations are respectively:", ["Parabolic, hyperbolic, elliptic", "Elliptic, parabolic, hyperbolic", "Hyperbolic, elliptic, parabolic", "All parabolic"], 0, "$B^2-4AC=0$ parabolic, $>0$ hyperbolic, $<0$ elliptic.", S13)
sa("pd-03", T, "Describe the method of separation of variables for a linear PDE.", "Assume $u(x,t)=X(x)T(t)$, substitute, and divide so each side depends on one variable. Set both sides equal to a separation constant $-\\lambda$. Solve the resulting ODEs, using the homogeneous BCs to get eigenvalues and eigenfunctions. Superpose the product solutions and fit the initial condition with a Fourier series.", "In this course the separation constant is written as $-\\lambda$, and you check the cases $\\lambda=0$, $\\lambda=-\\alpha^2$ and $\\lambda=\\alpha^2$.", S13, ["u = XT", "separation constant −λ", "eigenvalues", "superposition", "Fourier coefficients"])
tf("pd-04", T, "The superposition principle says that if $u_1,\\dots,u_k$ solve a homogeneous linear PDE, then any linear combination does too.", True, "This is why the series $\\sum A_n X_n T_n$ is still a solution.", S13)
mcq("pd-05", T, "For the heat equation with $u(0,t)=u(L,t)=0$, the eigenfunctions are:", ["$\\sin\\frac{n\\pi x}{L}$, $\\lambda_n=(n\\pi/L)^2$", "$\\cos\\frac{n\\pi x}{L}$", "$e^{n\\pi x/L}$", "$\\sinh\\frac{n\\pi x}{L}$"], 0, "The initial condition then becomes a half-range sine expansion of $f$.", S13)
mcq("pd-06", T, "Insulated ends of a rod ($u_x(0,t)=u_x(L,t)=0$) lead to:", ["A cosine series, including a constant term from $\\lambda_0=0$", "A sine series", "Only the zero solution", "Exponential eigenfunctions"], 0, "As $t\\to\\infty$ the temperature tends to the average of the initial distribution.", S13)
mcq("pd-07", T, "Which boundary condition is a Neumann condition?", ["$\\partial u/\\partial x=0$ at $x=0$", "$u=0$ at $x=0$", "$u_x=-h(u-u_m)$ at $x=L$", "$u(x,0)=f(x)$"], 0, "Dirichlet specifies $u$. Neumann specifies the normal derivative. Robin specifies a combination of both (e.g. convection).", S13)
tf("pd-08", T, "For the heat equation, each mode decays like $e^{-k(n\\pi/L)^2t}$, so higher modes die out faster.", True, "The solution smooths out quickly, so after a while the first term dominates.", S13)
mcq("pd-09", T, "The wave equation needs how many initial conditions?", ["Two: initial displacement $u(x,0)$ and initial velocity $u_t(x,0)$", "One: $u(x,0)$", "None", "Three"], 0, "It is second order in time. The heat equation is first order in time and needs one IC.", S13)
sa("pd-10", T, "For a vibrating string with fixed ends, what are the standing waves and the fundamental frequency?", "Each term $u_n=(A_n\\cos\\frac{n\\pi a}{L}t+B_n\\sin\\frac{n\\pi a}{L}t)\\sin\\frac{n\\pi x}{L}$ is a standing wave (normal mode). The $n=1$ mode is the first standing wave, with fundamental frequency $f_1=\\frac{a}{2L}$.", "Higher modes are overtones at integer multiples of $f_1$. Points with $\\sin(n\\pi x/L)=0$ are nodes.", S13, ["standing waves", "fundamental frequency a/2L", "nodes"])
mcq("pd-11", T, "In the steady-state (Dirichlet) problem for Laplace's equation on a rectangle with three zero edges, the $y$-dependence typically uses:", ["$\\sinh$ or $\\cosh$", "$\\sin$ or $\\cos$", "decaying exponentials in $t$", "polynomials"], 0, "The direction with homogeneous BCs gets $\\sin$ (eigenfunctions). The other direction gets $\\sinh/\\cosh$.", S13)
tf("pd-12", T, "If a rectangle has nonzero temperatures on two edges, you can split it into two problems (each with one nonzero edge) and add the solutions.", True, "This is the superposition principle for Laplace's equation.", S13)
sa("pd-13", T, "How do you handle a heat problem with nonhomogeneous, time-independent BCs (e.g. $u(0,t)=u_0$, $u(L,t)=u_1$)?", "Write $u=v(x,t)+\\psi(x)$. $\\psi$ is the steady-state solution satisfying $k\\psi''=0$ (plus any source term) and the nonhomogeneous BCs. $v$ satisfies the heat equation with homogeneous BCs and the IC $v(x,0)=f(x)-\\psi(x)$. Then $u\\to\\psi$ as $t\\to\\infty$.", "Section 13.6. With no source, $\\psi$ is the straight line between the end temperatures.", S13, ["u = v + ψ", "steady state", "homogeneous BCs for v"])
mcq("pd-14", T, "In the separated heat problem, what does the $T(t)$ equation look like?", ["$T'+k\\lambda T=0$, giving $T=e^{-k\\lambda t}$", "$T''+a^2\\lambda T=0$", "$T'=\\lambda T$ with growth", "$T=$ constant"], 0, "With $\\lambda>0$ the solution decays, as heat physically must.", S13)
